from io import StringIO
import pytest
from isort.core import process
from isort.settings import Config, DEFAULT_CONFIG
from isort.exceptions import ExistingSyntaxErrors, FileSkipComment

def test_process_full_coverage():
    # 1. Test float_to_top with # isort: off, # isort: on, # isort: split, and add_imports
    content_float = (
        "# isort: off\n"
        "x = 1\n"
        "# isort: on\n"
        "import os\n"
        "# isort: split\n"
        "import sys\n"
    )
    inp = StringIO(content_float)
    out = StringIO()
    config = Config(float_to_top=True, add_imports=["print"])
    changed = process(inp, out, config=config)
    assert isinstance(changed, bool)

    # 2. Test empty input stream with force_adds=False
    inp = StringIO("")
    out = StringIO()
    assert process(inp, out, config=Config(force_adds=False)) is False

    # 3. Test FileSkipComment raising / skipping
    inp = StringIO("# isort: skip_file\n")
    out = StringIO()
    with pytest.raises(FileSkipComment):
        process(inp, out, raise_on_skip=True)

    inp = StringIO("# isort: skip_file\n")
    out = StringIO()
    process(inp, out, raise_on_skip=False)

    # 4. Test # isort: dont-add-imports and dont-add-import:
    inp = StringIO(
        "# isort: dont-add-imports\n"
        "# isort: dont-add-import: b\n"
        "import a\n"
    )
    out = StringIO()
    process(inp, out, config=Config(add_imports=["b", "c"]))

    # 5. Test in_top_comment using DEFAULT_CONFIG
    inp = StringIO(
        "# Top comment\n"
        "# Another top comment\n"
        "import os\n"
    )
    out = StringIO()
    process(inp, out, config=DEFAULT_CONFIG)

    # 6. Test quote handling, backslashes, multiline quotes, and top comment indexing
    inp = StringIO(
        '"""Docstring"""\n'
        "a = 'hello\\'world'\n"
        "b = '''multiline\nquote'''\n"
        "import sys\n"
    )
    out = StringIO()
    process(inp, out)

    # 7. Test # isort: split inside code
    inp = StringIO(
        "import os\n"
        "# isort: split\n"
        "import sys\n"
    )
    out = StringIO()
    process(inp, out)

    # 8. Test code sorting comments and reexports (__all__) with valid single-line assignment format
    inp = StringIO(
        "# isort: list\n"
        "a = ['z', 'y']\n"
        "\n"
        "__all__ = ['b', 'a']\n"
    )
    out = StringIO()
    process(inp, out, config=Config(sort_reexports=True))

    # 9. Test section comments using DEFAULT_CONFIG
    inp = StringIO(
        "# Third Party\n"
        "import os\n"
    )
    out = StringIO()
    process(inp, out, config=DEFAULT_CONFIG)

    # 10. Test treat_all_comments_as_code and comments treatment
    inp = StringIO(
        "# Regular comment treated as code\n"
        "import os\n"
    )
    out = StringIO()
    process(inp, out, config=Config(treat_all_comments_as_code=True))

    # 11. Test import statements with backslash continuation and unclosed parenthesis (ExistingSyntaxErrors)
    inp = StringIO(
        "from os import \\\n"
        "    path\n"
    )
    out = StringIO()
    process(inp, out)

    inp = StringIO(
        "from os import (\n"
        "    path\n"
    )
    out = StringIO()
    with pytest.raises(ExistingSyntaxErrors):
        process(inp, out)

    # 12. Test 'from' without 'import'
    inp = StringIO(
        "from os\n"
        "import sys\n"
    )
    out = StringIO()
    process(inp, out)

    # 13. Test cimports (cython / cimport identifiers)
    inp = StringIO(
        "cimport cython\n"
        "import os\n"
    )
    out = StringIO()
    process(inp, out, extension="pyx")

    # 14. Test lines_before_imports and append_only
    inp = StringIO(
        "\n"
        "\n"
        "import os\n"
    )
    out = StringIO()
    process(inp, out, config=Config(lines_before_imports=2, append_only=True))

    # 15. Test docstring indicators and comment indicators with add_imports
    inp = StringIO(
        '"""Module docstring"""\n'
        "x = 1\n"
    )
    out = StringIO()
    process(inp, out, config=Config(add_imports=["sys"]))

    # 16. Test indent with import sections and next_import_section
    inp = StringIO(
        "if True:\n"
        "    import b\n"
        "    import a\n"
    )
    out = StringIO()
    process(inp, out)

    # 17. Test yield and raise statements with continuation lines
    inp = StringIO(
        "yield \\\n"
        "    value\n"
        "raise \\\n"
        "    RuntimeError\n"
    )
    out = StringIO()
    process(inp, out)

    # 18. Test made_changes and only_modified with verbose_output
    inp = StringIO("import b\nimport a\n")
    out = StringIO()
    config = Config(only_modified=True, verbose=True)
    process(inp, out, config=config)
